css:
/* ===== pele — carrossel reforma tributária / arrendamento rural ===== */

@import url('https://fonts.googleapis.com/css2?family=Anton&family=Baloo+2:wght@400;700&display=swap');

.slide {
  width: 1080px;
  height: 1350px;
  box-sizing: border-box;
  overflow: hidden;
  position: relative;
  font-family: 'Baloo 2', sans-serif;
}

/* ---------- capa (slide 1): foto full-bleed + headline grotesca condensada ---------- */

.slide-capa {
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.bg-01 { background-color: #6A5033; }

.overlay-top {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(
    to bottom,
    rgba(8, 10, 12, 0.5) 0%,
    rgba(8, 10, 12, 0.2) 30%,
    rgba(8, 10, 12, 0) 55%
  );
}

.headline-wrap {
  position: absolute;
  top: 140px;
  left: 97px;
  right: 97px;
  text-align: center;
}

.headline {
  margin: 0;
  font-family: 'Anton', sans-serif;
  font-weight: 400;
  text-transform: uppercase;
  font-size: 48px;
  line-height: 1.15;
  letter-spacing: 0;
  color: #FFFFFF;
  text-shadow: 0 3px 14px rgba(0, 0, 0, 0.55);
}

/* ---------- slides de papel (2,4,6,8): fundo bege com vinco, leitura corrida ---------- */

.slide-paper {
  background-color: #E9E5E2;
  background-image:
    linear-gradient(90deg, transparent 49.6%, rgba(20, 15, 10, 0.05) 50%, transparent 50.4%),
    linear-gradient(0deg, transparent 38.6%, rgba(20, 15, 10, 0.045) 39%, transparent 39.4%),
    radial-gradient(ellipse at 30% 70%, rgba(0, 0, 0, 0.03), transparent 60%);
}

.texto-paper {
  position: absolute;
  left: 97px;
  right: 97px;
  top: 300px;
}

.texto-paper--alto {
  top: 150px;
}

.slide-paper .header-bloco {
  color: #2E2C2A;
}

.slide-paper .paragrafo,
.slide-paper .negrito {
  color: #464544;
}

/* ---------- slides de foto com legenda (3,5,7,9,10): texto ancorado na base ---------- */

.slide-foto {
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.bg-03 { background-color: #59721E; }
.bg-05 { background-color: #A98131; }
.bg-07 { background-color: #425122; }
.bg-09 { background-color: #563D1E; }
.bg-10 { background-color: #462817; }

.overlay-bottom {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.78) 0%,
    rgba(0, 0, 0, 0.55) 25%,
    rgba(0, 0, 0, 0.15) 55%,
    rgba(0, 0, 0, 0) 75%
  );
}

.texto-foto {
  position: absolute;
  left: 97px;
  right: 97px;
  bottom: 95px;
}

.slide-foto .header-bloco,
.slide-foto .paragrafo,
.slide-foto .negrito {
  color: #FFFFFF;
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.45);
}

/* ---------- tipografia comum de bloco de texto ---------- */

.header-bloco {
  margin: 0 0 27px 0;
  font-family: 'Baloo 2', sans-serif;
  font-weight: 700;
  font-size: 62px;
  line-height: 1.1;
}

.paragrafo {
  margin: 0 0 34px 0;
  font-family: 'Baloo 2', sans-serif;
  font-weight: 400;
  font-size: 52px;
  line-height: 1.15;
}

.paragrafo:last-child {
  margin-bottom: 0;
}

.negrito {
  margin: 13px 0 0 0;
  font-family: 'Baloo 2', sans-serif;
  font-weight: 700;
  font-size: 52px;
  line-height: 1.15;
}

/* ---------- destaque (slide 5): caixa sólida marrom-alaranjada atrás do parágrafo ---------- */

.destaque-box {
  display: block;
  background-color: rgba(120, 66, 15, 0.82);
  padding: 34px 42px;
  box-sizing: border-box;
  text-shadow: none;
}
